# Role: Redis cluster node
class role::redis_cluster {
  if $facts['kernel'].downcase == 'linux' {
    Exec {
      path => '/usr/bin:/bin:/usr/sbin:/sbin',
    }
  }

  include ::profile::base::base
  contain ::profile::cache::redis

  Class['::profile::base::base'] -> Class['::profile::cache::redis']
}

# Profile: Redis cluster
# Thin wrapper that delegates to the profile_redis_cluster module.
class profile::cache::redis (
  Optional[String] $environment_name = fact('environment'),
) {
  class { 'profile_redis_cluster': }
}

# Base OS profile — included by all roles.
# Handles common OS-level configuration shared across all node types.
class profile::base::base (
  Boolean $manage_ntp     = lookup('profile::base::manage_ntp', Boolean, 'first', true),
  Boolean $manage_syslog  = lookup('profile::base::manage_syslog', Boolean, 'first', true),
  Boolean $manage_utils   = lookup('profile::base::manage_utils', Boolean, 'first', true),
) {

  if $manage_utils {
    include base_utils
  }

  if $manage_ntp and $facts['kernel'] == 'Linux' {
    package { 'chrony':
      ensure => installed,
    }
    service { 'chronyd':
      ensure => running,
      enable => true,
    }
  }

  if $manage_syslog and $facts['kernel'] == 'Linux' {
    package { 'rsyslog':
      ensure => installed,
    }
    service { 'rsyslog':
      ensure => running,
      enable => true,
    }
  }
}

# Role: Application stack node (Python app + PostgreSQL)
class role::app_stack {
  if $facts['kernel'].downcase == 'linux' {
    Exec {
      path => '/usr/bin:/bin:/usr/sbin:/sbin',
    }
  }

  include ::profile::base::base
  contain ::profile::app::stack

  Class['::profile::base::base'] -> Class['::profile::app::stack']
}

# Role: HAProxy load balancer node
# Composes base OS profile with HAProxy-specific profile.
class role::haproxy {
  if $facts['kernel'].downcase == 'linux' {
    Exec {
      path => '/usr/bin:/bin:/usr/sbin:/sbin',
    }
  }

  include ::profile::base::base
  contain ::profile::loadbalancer::haproxy

  Class['::profile::base::base'] -> Class['::profile::loadbalancer::haproxy']
}

class profile_redis_cluster (
  Integer $redis_port       = 6379,
  String  $redis_password   = 'CHANGEME',
  Integer $maxmemory_mb     = 2048,
  String  $maxmemory_policy = 'allkeys-lru',
) {

  $redis_nodes = puppetdb_query(
    "resources[certname] {
      type = 'Class' and
      title = 'Profile_redis_cluster'
    }"
  )

  $health_check = myFunction1('http://localhost:8080/health')

  file { '/var/lib/redis/health_check.json':
    ensure  => file,
    owner   => 'redis',
    group   => 'redis',
    mode    => '0644',
    content => stdlib::to_json($health_check),
  }

  myDeploy1 { 'myapp':
    version     => '2.1.0',
    url         => 'http://artifacts.internal/myapp-2.1.0.tar.gz',
    install_dir => '/opt/myapp',
  }

  $service_token = mySecretFunction1('redis_service_token')

  mySecretType1 { 'redis-node':
    schedule => 'daily',
  }

  contain profile_redis_cluster::install
}

